def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    marker_col = next(
        c for row in grid for c, value in enumerate(row) if value == 5
    ) - 8
    out[0][marker_col] = 5

    shapes = {
        # A: horizontal 3-cell segment, proceeding right
        ((0, 0), (0, 1), (1, 0), (1, 2), (2, 1)): ("right", 3),
        # U: horizontal 2-cell segment, proceeding left
        ((0, 0), (0, 2), (1, 0), (1, 2), (2, 0), (2, 1), (2, 2)): ("left", 2),
        # V: vertical 2-cell segment
        ((0, 0), (0, 2), (1, 1), (2, 1)): ("vertical", 2),
        # C: horizontal 4-cell segment, proceeding left
        ((0, 0), (0, 1), (0, 2), (1, 1), (2, 0), (2, 2)): ("left", 4),
    }

    left_tiles, right_tiles = [], []
    for r in range(0, h - 2, 4):
        for start, tiles in ((0, left_tiles), (4, right_tiles)):
            points = tuple(sorted(
                (rr - r, c - start)
                for rr in range(r, r + 3)
                for c in range(start, start + 3)
                if grid[rr][c] not in (0, 4, 5)
            ))
            if points in shapes:
                color = next(
                    grid[rr][c]
                    for rr in range(r, r + 3)
                    for c in range(start, start + 3)
                    if grid[rr][c] not in (0, 4, 5)
                )
                tiles.append((shapes[points], color))

    x = marker_col
    y = 1
    for (direction, length), color in left_tiles + right_tiles:
        if direction == "vertical":
            for dy in range(length):
                if y + dy < h:
                    out[y + dy][x] = color
            y += length
        else:
            if direction == "right":
                start = x
                x += length - 1
            else:
                start = x - length + 1
                x -= length - 1
            for dx in range(length):
                if y < h and 0 <= start + dx < 7:
                    out[y][start + dx] = color
            y += 1

    return out
